import{_ as s,o as i,c as t,a3 as r,j as e,a}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/sekundarstufen/gruppenprozesse-zp10-pruefungsnoten-eintragen.png",f=JSON.parse('{"title":"ZP10-Prüfungsnoten gruppenweise eingeben","description":"","frontmatter":{"title":"ZP10-Prüfungsnoten gruppenweise eingeben","source_pageid":1160,"source_revision":3921},"headers":[],"relativePath":"zeugnisse/sekundarstufen/noten-eingeben-gruppenprozesse-zentrale-klausuren.md","filePath":"zeugnisse/sekundarstufen/noten-eingeben-gruppenprozesse-zentrale-klausuren.md"}'),u={name:"zeugnisse/sekundarstufen/noten-eingeben-gruppenprozesse-zentrale-klausuren.md"};function p(d,n,l,g,c,m){return i(),t("div",null,[...n[0]||(n[0]=[r('<h1 id="zp10-prufungsnoten-gruppenweise-eingeben" tabindex="-1">ZP10-Prüfungsnoten gruppenweise eingeben <a class="header-anchor" href="#zp10-prufungsnoten-gruppenweise-eingeben" aria-label="Permalink to &quot;ZP10-Prüfungsnoten gruppenweise eingeben&quot;">​</a></h1><p>Erfassen Sie Prüfungsnoten direkt für eine ausgewählte Schülergruppe. Die Fachstrukturen müssen zuvor über Leistungsdaten holen angelegt worden sein.</p><p><a href="/bilder/sekundarstufen/gruppenprozesse-zp10-pruefungsnoten-eintragen.png"><img src="'+o+'" alt="Geben Sie Prüfungsnoten manuell nach Fach oder dem Namen sortiert ein." loading="lazy"></a></p><p><em>Geben Sie Prüfungsnoten manuell nach Fach oder dem Namen sortiert ein.</em></p><p>Die Noten können auch direkt eingegeben werden, so dass keine Teilleistungen erfasst werden müssen. Hierzu dient der Gruppenprozess <strong>Prüfungsnoten eingeben</strong>.</p><p>Zuerst müssen die Leistungsdaten bei den Schülern im Reiter <em>Schüler ➜ ZP 10/ZK</em> vorliegen. Hierzu ist der Gruppenprozess <em>Leistungsdaten holen</em> zuerst auszuführen.</p><p>Nun ist auf die Gruppe zu filtern, für die der Gruppenprozess <strong>Prüfungsnoten eingeben</strong> ausgeführt werden soll.</p>',7),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),a("Beispiel")]),e("p",null,"In Fällen, in denen die Listen kursweise vorliegen, wäre es sinnvoll, im Schülercontainer auf diesen Kurs zu filtern. Hilfreich könnte dies zum Beispiel sein, wenn eine Lehrkraft den Eintragtermin verpassen musste, aber eine Kursliste mit den Noten einreichen konnte, so dass dieser Kurs nun effektiv nachgetragen werden kann.")],-1),r(`<p>Bei der <strong>Sortierung</strong> kann gewählt werden, ob erst nach <em>Fach</em> und dann nach <em>Name</em> oder erst nach <em>Name</em> und dann nach <em>Fach</em> sortiert wird.</p><p>Dieser erste Fall ist im Screenshot zu sehen. Im zweiten Fall könnte die Liste so aufgebaut sein:</p><pre><code> Adam, Melanie, D
 Adam, Melanie, E
 Adam, Melanie, M
 Adams, Jessica, D
 Adams, Jessica, E
 Adams, Jessica, M
</code></pre><p>und so weiter.</p><p>Tragen Sie die Noten wie vorliegend und benötigt ein, klicken Sie dann auf <code>In Datenbank übernehmen</code>.</p><p>Ein Klick auf <code>Abbrechen</code> beendet den Gruppenprozess, ohne dass Änderungen an der Datenbank vorgenommen werden und eventuell hier vorgenommene Eintragungen werden verworfen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Noten_eingeben_(Gruppenprozesse_Zentrale_Klausuren)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 3921.</p>`,8)])])}const _=s(u,[["render",p]]);export{f as __pageData,_ as default};
